#include <stdio.h>
#include <string.h>

const char* trafficLight(int state) {
    int n = state;
    int m = 0;

    if (n == 1) {
        return "red";
    }

    m = n - 1;
    if (m == 1) {
        return "yellow";
    }

    m = n - 2;
    if (m == 1) {
        return "green";
    }

    return "unknown";
}

int main() {
    printf("%s\n", trafficLight(1));
    printf("%s\n", trafficLight(2));
    printf("%s\n", trafficLight(3));
    printf("%s\n", trafficLight(0));
    printf("%s\n", trafficLight(4));
    printf("%s\n", trafficLight(-1));
    printf("%s\n", trafficLight(100));

    return 0;
}

