import java.util.*;

public class Solution {
    public static String trafficLight(int state) {
        int n = state;
        int m = 0;

        if (n == 1) {
            m = 1;
        } else if (n == 2) {
            m = 2;
        } else if (n == 3) {
            m = 3;
        } else {
            m = 0;
        }

        if (m == 1) {
            return "red";
        } else if (m == 2) {
            return "yellow";
        } else if (m == 3) {
            return "green";
        } else {
            return "unknown";
        }
    }

    public static void main(String[] args) {
        System.out.println(trafficLight(1));
        System.out.println(trafficLight(2));
        System.out.println(trafficLight(3));
        System.out.println(trafficLight(0));
        System.out.println(trafficLight(4));
        System.out.println(trafficLight(-1));
        System.out.println(trafficLight(100));
    }
}
